1	package main
2	
3	import (
4		"bytes"
5		"context"
6		"crypto/rand"
7		"encoding/hex"
8		"encoding/json"
9		"errors"
10		"flag"
11		"fmt"
12		"io"
13		"net"
14		"net/http"
15		"os"
16		"os/signal"
17		"path/filepath"
18		"sort"
19		"strings"
20		"sync"
21		"syscall"
22		"time"
23	)
24	
25	const product = "CaseDock"
26	const resourceName = "tickets"
27	
28	// timeLayout 使用固定宽度的小数位，保证字符串按时间先后可比较。
29	const timeLayout = "2006-01-02T15:04:05.000000000Z07:00"
30	
31	// validSources / validPriorities 是页面与接口共用的合法选项。
32	var validSources = []string{"在线", "电话", "邮件"}
33	var validPriorities = []string{"低", "普通", "高", "紧急"}
34	
35	// ticketInput 是登记接口接收的字段，全部按文字处理。
36	type ticketInput struct {
37		Description    string `json:"description"`
38		ContactName    string `json:"contactName"`
39		ContactInfo    string `json:"contactInfo"`
40		Source         string `json:"source"`
41		Category       string `json:"category"`
42		Priority       string `json:"priority"`
43		AttachmentNote string `json:"attachmentNote"`
44		OrderNumber    string `json:"orderNumber"`
45		SubmitID       string `json:"submitId"`
46	}
47	
48	// ticket 是保存并返回的工单记录。
49	type ticket struct {
50		ID             string `json:"id"`
51		Description    string `json:"description"`
52		ContactName    string `json:"contactName"`
53		ContactInfo    string `json:"contactInfo"`
54		Source         string `json:"source"`
55		Category       string `json:"category"`
56		Priority       string `json:"priority"`
57		AttachmentNote string `json:"attachmentNote"`
58		OrderNumber    string `json:"orderNumber"`
59		Status         string `json:"status"`
60		Assignee       string `json:"assignee"`
61		CreatedAt      string `json:"createdAt"`
62		UpdatedAt      string `json:"updatedAt"`
63	}
64	
65	// storeFile 是磁盘上的持久化结构。submitIds 与 tickets 按位置一一对应。
66	type storeFile struct {
67		Seq       int      `json:"seq"`
68		Tickets   []ticket `json:"tickets"`
69		SubmitIDs []string `json:"submitIds"`
70	}
71	
72	// ticketStore 持久化工单与已成功的提交标识，所有方法并发安全。
73	type ticketStore struct {
74		mu       sync.Mutex
75		path     string
76		seq      int
77		tickets  []ticket
78		bySubmit map[string]int // submitId -> tickets 下标
79	}
80	
81	func loadStore(path string) (*ticketStore, error) {
82		s := &ticketStore{path: path, tickets: []ticket{}, bySubmit: map[string]int{}}
83		raw, err := os.ReadFile(path)
84		if err != nil {
85			return nil, err
86		}
87		var data storeFile
88		if err := json.Unmarshal(raw, &data); err != nil {
89			// 兼容旧版本的纯数组文件 []。
90			var legacy []ticket
91			if legacyErr := json.Unmarshal(raw, &legacy); legacyErr != nil {
92				return nil, err
93			}
94			data.Tickets = legacy
95		}
96		if data.Tickets != nil {
97			s.tickets = data.Tickets
98		}
99		s.seq = data.Seq
100		for i, t := range s.tickets {
101			// 编号是重启后不重复的最终依据；旧数据缺少 seq 时从编号恢复。
102			var n int
103			if _, scanErr := fmt.Sscanf(t.ID, "TKT-%d", &n); scanErr == nil && n > s.seq {
104				s.seq = n
105			}
106			if i < len(data.SubmitIDs) && data.SubmitIDs[i] != "" {
107				s.bySubmit[data.SubmitIDs[i]] = i
108			}
109		}
110		return s, nil
111	}
112	
113	// persistLocked 将当前数据原子写入磁盘，调用方须持有 s.mu。
114	func (s *ticketStore) persistLocked() error {
115		ids := make([]string, len(s.tickets))
116		for id, i := range s.bySubmit {
117			if i >= 0 && i < len(ids) {
118				ids[i] = id
119			}
120		}
121		data := storeFile{Seq: s.seq, Tickets: s.tickets, SubmitIDs: ids}
122		buf, err := json.MarshalIndent(data, "", "  ")
123		if err != nil {
124			return err
125		}
126		buf = append(buf, '\n')
127		tmp := s.path + ".tmp"
128		if err := os.WriteFile(tmp, buf, 0600); err != nil {
129			return err
130		}
131		return os.Rename(tmp, s.path)
132	}
133	
134	var errConflict = errors.New("submit id reused with different content")
135	
136	// create 校验后的数据登记为工单。同一提交标识、相同内容为幂等重放，
137	// 返回已有工单且 replay=true；同一标识不同内容返回 errConflict 且不改数据。
138	func (s *ticketStore) create(in ticketInput) (t ticket, replay bool, err error) {
139		s.mu.Lock()
140		defer s.mu.Unlock()
141		if idx, ok := s.bySubmit[in.SubmitID]; ok {
142			existing := s.tickets[idx]
143			if sameTicketContent(existing, in) {
144				return existing, true, nil
145			}
146			return ticket{}, false, errConflict
147		}
148		s.seq++
149		now := time.Now().Format(timeLayout)
150		t = ticket{
151			ID:             fmt.Sprintf("TKT-%06d", s.seq),
152			Description:    in.Description,
153			ContactName:    in.ContactName,
154			ContactInfo:    in.ContactInfo,
155			Source:         in.Source,
156			Category:       in.Category,
157			Priority:       in.Priority,
158			AttachmentNote: in.AttachmentNote,
159			OrderNumber:    in.OrderNumber,
160			Status:         "待处理",
161			Assignee:       "未分派",
162			CreatedAt:      now,
163			UpdatedAt:      now,
164		}
165		s.tickets = append(s.tickets, t)
166		s.bySubmit[in.SubmitID] = len(s.tickets) - 1
167		if err := s.persistLocked(); err != nil {
168			// 保存失败：回滚内存中的本次变更，登记不算完成。
169			delete(s.bySubmit, in.SubmitID)
170			s.tickets = s.tickets[:len(s.tickets)-1]
171			s.seq--
172			return ticket{}, false, err
173		}
174		return t, false, nil
175	}
176	
177	// list 返回按创建时间从新到旧排列的工单副本。
178	func (s *ticketStore) list() []ticket {
179		s.mu.Lock()
180		defer s.mu.Unlock()
181		out := make([]ticket, len(s.tickets))
182		copy(out, s.tickets)
183		sort.SliceStable(out, func(i, j int) bool {
184			if out[i].CreatedAt != out[j].CreatedAt {
185				return out[i].CreatedAt > out[j].CreatedAt
186			}
187			return out[i].ID > out[j].ID
188		})
189		return out
190	}
191	
192	// sameTicketContent 按文字处理规则比较已有工单与本次提交（提交标识除外）。
193	func sameTicketContent(t ticket, in ticketInput) bool {
194		return t.Description == in.Description &&
195			t.ContactName == in.ContactName &&
196			t.ContactInfo == in.ContactInfo &&
197			t.Source == in.Source &&
198			t.Category == in.Category &&
199			t.Priority == in.Priority &&
200			t.AttachmentNote == in.AttachmentNote &&
201			t.OrderNumber == in.OrderNumber
202	}
203	
204	// validateInput 按页面与接口一致的规则校验，并对文字字段去除首尾空白。
205	// 描述与附件说明只去除整体首尾空白，正文内部换行保留。
206	func validateInput(in *ticketInput) error {
207		in.Description = strings.TrimSpace(in.Description)
208		in.ContactName = strings.TrimSpace(in.ContactName)
209		in.ContactInfo = strings.TrimSpace(in.ContactInfo)
210		in.Source = strings.TrimSpace(in.Source)
211		in.Category = strings.TrimSpace(in.Category)
212		in.Priority = strings.TrimSpace(in.Priority)
213		in.AttachmentNote = strings.TrimSpace(in.AttachmentNote)
214		// 联系方式与订单号始终是字符串，不做数字转换，前导零不会丢失。
215		in.OrderNumber = strings.TrimSpace(in.OrderNumber)
216		in.SubmitID = strings.TrimSpace(in.SubmitID)
217	
218		var missing []string
219		for _, f := range []struct{ name, value string }{
220			{"description", in.Description},
221			{"contactName", in.ContactName},
222			{"contactInfo", in.ContactInfo},
223			{"category", in.Category},
224			{"submitId", in.SubmitID},
225		} {
226			if f.value == "" {
227				missing = append(missing, f.name)
228			}
229		}
230		if len(missing) > 0 {
231			return fmt.Errorf("missing or empty required fields: %s", strings.Join(missing, ", "))
232		}
233		if !oneOf(in.Source, validSources) {
234			return fmt.Errorf("invalid source: %q; allowed: %s", in.Source, strings.Join(validSources, "/"))
235		}
236		if !oneOf(in.Priority, validPriorities) {
237			return fmt.Errorf("invalid priority: %q; allowed: %s", in.Priority, strings.Join(validPriorities, "/"))
238		}
239		return nil
240	}
241	
242	func oneOf(v string, allowed []string) bool {
243		for _, a := range allowed {
244			if v == a {
245				return true
246			}
247		}
248		return false
249	}
250	
251	func newSubmitID() string {
252		b := make([]byte, 16)
253		if _, err := rand.Read(b); err != nil {
254			// rand 失败极不可能发生；退回纳秒时间戳仍能给出非空标识。
255			return fmt.Sprintf("sub-%d", time.Now().UnixNano())
256		}
257		return "sub-" + hex.EncodeToString(b)
258	}
259	
260	func respond(w http.ResponseWriter, status int, allow string, value any) {
261		w.Header().Set("Content-Type", "application/json; charset=utf-8")
262		if allow != "" {
263			w.Header().Set("Allow", allow)
264		}
265		w.WriteHeader(status)
266		_ = json.NewEncoder(w).Encode(value)
267	}
268	
269	func run() error {
270		if len(os.Args) < 2 {
271			printHelp()
272			return errors.New("expected serve or --help")
273		}
274		if os.Args[1] == "--help" || os.Args[1] == "-h" {
275			printHelp()
276			return nil
277		}
278		if os.Args[1] != "serve" {
279			return errors.New("expected serve or --help")
280		}
281		args := flag.NewFlagSet("case-dock serve", flag.ContinueOnError)
282		args.SetOutput(os.Stdout)
283		host := args.String("host", "127.0.0.1", "address to bind")
284		port := args.Int("port", 8080, "port to bind; 0 selects an available port")
285		data := args.String("data-dir", "data", "directory for local records")
286		if err := args.Parse(os.Args[2:]); errors.Is(err, flag.ErrHelp) {
287			return nil
288		} else if err != nil {
289			return err
290		}
291		if args.NArg() != 0 {
292			return errors.New("unexpected positional argument")
293		}
294		if *port < 0 || *port > 65535 {
295			return errors.New("port must be between 0 and 65535")
296		}
297		if err := os.MkdirAll(*data, 0700); err != nil {
298			return err
299		}
300		dataFile := filepath.Join(*data, "tickets.json")
301		if _, err := os.Stat(dataFile); errors.Is(err, os.ErrNotExist) {
302			buf, err := json.MarshalIndent(storeFile{Seq: 0, Tickets: []ticket{}, SubmitIDs: []string{}}, "", "  ")
303			if err != nil {
304				return err
305			}
306			buf = append(buf, '\n')
307			if err := os.WriteFile(dataFile, buf, 0600); err != nil {
308				return err
309			}
310		} else if err != nil {
311			return err
312		}
313		store, err := loadStore(dataFile)
314		if err != nil {
315			return fmt.Errorf("load %s: %w", dataFile, err)
316		}
317	
318		mux := http.NewServeMux()
319		mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
320			if r.URL.Path != "/" {
321				respond(w, http.StatusNotFound, "", map[string]string{"error": "not found"})
322				return
323			}
324			if r.Method != http.MethodGet {
325				respond(w, http.StatusMethodNotAllowed, "GET", map[string]string{"error": "method not allowed"})
326				return
327			}
328			w.Header().Set("Content-Type", "text/html; charset=utf-8")
329			_, _ = io.WriteString(w, page)
330		})
331		mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
332			if r.Method != http.MethodGet {
333				respond(w, http.StatusMethodNotAllowed, "GET", map[string]string{"error": "method not allowed"})
334				return
335			}
336			respond(w, http.StatusOK, "", map[string]string{"status": "ok", "product": product})
337		})
338		mux.HandleFunc("/api/tickets", func(w http.ResponseWriter, r *http.Request) {
339			switch r.Method {
340			case http.MethodGet:
341				tickets := store.list()
342				respond(w, http.StatusOK, "", map[string]any{resourceName: tickets})
343			case http.MethodPost:
344				body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
345				if err != nil {
346					respond(w, http.StatusBadRequest, "", map[string]string{"error": "unable to read request body"})
347					return
348				}
349				dec := json.NewDecoder(bytes.NewReader(body))
350				var in ticketInput
351				if decErr := dec.Decode(&in); decErr != nil {
352					if errors.Is(decErr, io.EOF) {
353						decErr = errors.New("request body is empty")
354					}
355					respond(w, http.StatusBadRequest, "", map[string]string{"error": "invalid JSON: " + decErr.Error()})
356					return
357				}
358				var tail json.RawMessage
359				if decErr := dec.Decode(&tail); !errors.Is(decErr, io.EOF) {
360					respond(w, http.StatusBadRequest, "", map[string]string{"error": "invalid JSON: trailing data after the JSON object"})
361					return
362				}
363				if err := validateInput(&in); err != nil {
364					respond(w, http.StatusBadRequest, "", map[string]string{"error": err.Error()})
365					return
366				}
367				t, replay, err := store.create(in)
368				if errors.Is(err, errConflict) {
369					respond(w, http.StatusConflict, "", map[string]string{"error": "submit id was already used with different content"})
370					return
371				}
372				if err != nil {
373					respond(w, http.StatusInternalServerError, "", map[string]string{"error": "unable to save ticket"})
374					return
375				}
376				status := http.StatusCreated
377				if replay {
378					status = http.StatusOK
379				}
380				respond(w, status, "", t)
381			default:
382				respond(w, http.StatusMethodNotAllowed, "GET, POST", map[string]string{"error": "method not allowed"})
383			}
384		})
385	
386		server := &http.Server{
387			Handler:           mux,
388			ReadHeaderTimeout: 5 * time.Second,
389		}
390		listener, err := net.Listen("tcp", net.JoinHostPort(*host, fmt.Sprint(*port)))
391		if err != nil {
392			return err
393		}
394		fmt.Printf("%s listening on http://%s\n", product, listener.Addr().String())
395		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
396		defer stop()
397		failures := make(chan error, 1)
398		go func() { failures <- server.Serve(listener) }()
399		select {
400		case err := <-failures:
401			if !errors.Is(err, http.ErrServerClosed) {
402				return err
403			}
404		case <-ctx.Done():
405			shutdown, cancel := context.WithTimeout(context.Background(), 3*time.Second)
406			defer cancel()
407			if err := server.Shutdown(shutdown); err != nil {
408				return err
409			}
410		}
411		return nil
412	}
413	
414	func printHelp() {
415		fmt.Println("CaseDock - 客服工单与知识服务")
416		fmt.Println("Usage: go run . serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]")
417		fmt.Println("       go run . --help")
418		fmt.Println("Defaults: --host 127.0.0.1 --port 8080 --data-dir data")
419	}
420	
421	func main() {
422		if err := run(); err != nil {
423			fmt.Fprintln(os.Stderr, err)
424			os.Exit(1)
425		}
426	}
