25	const product = "CaseDock"
26	const resourceName = "tickets"
27	
28	// timeLayout 使用固定宽度的小数位，保证字符串按时间先后可比较。
29	const timeLayout = "2006-01-02T15:04:05.000000000Z07:00"
30	
31	// validSources / validPriorities 是页面与接口共用的合法选项。
32	var validSources = []string{"在线", "电话", "邮件"}
33	var validPriorities = []string{"低", "普通", "高", "紧急"}
34	
35	// ticketInput 是登记接口接收的字段，全部按文字处理。
36	type ticketInput struct {
37		Description    string `json:"description"`
38		ContactName    string `json:"contactName"`
39		ContactInfo    string `json:"contactInfo"`
40		Source         string `json:"source"`
41		Category       string `json:"category"`
42		Priority       string `json:"priority"`
43		AttachmentNote string `json:"attachmentNote"`
44		OrderNumber    string `json:"orderNumber"`
45		SubmitID       string `json:"submitId"`
46	}
47	
48	// ticket 是保存并返回的工单记录。
49	type ticket struct {
50		ID             string             `json:"id"`
51		Description    string             `json:"description"`
52		ContactName    string             `json:"contactName"`
53		ContactInfo    string             `json:"contactInfo"`
54		Source         string             `json:"source"`
55		Category       string             `json:"category"`
56		Priority       string             `json:"priority"`
57		AttachmentNote string             `json:"attachmentNote"`
58		OrderNumber    string             `json:"orderNumber"`
59		Status         string             `json:"status"`
60		Assignee       string             `json:"assignee"`
61		CreatedAt      string             `json:"createdAt"`
62		UpdatedAt      string             `json:"updatedAt"`
63		Assignments    []assignmentRecord `json:"assignments"`
64	}
65	
66	// assignmentRecord 是一次分派或转交记录，保存原负责人、新负责人与发生时间。
67	type assignmentRecord struct {
68		From string `json:"from"`
69		To   string `json:"to"`
70		At   string `json:"at"`
71	}
72	
73	// assignmentInput 是分派接口接收的字段，全部按文字处理。
74	type assignmentInput struct {
75		Assignee    string `json:"assignee"`
76		OperationID string `json:"operationId"`
77	}
78	
79	// storeFile 是磁盘上的持久化结构。submitIds 与 tickets 按位置一一对应；
80	// opIds 按工单编号保存每张工单已成功的分派操作标识及其负责人。
81	type storeFile struct {
82		Seq       int                          `json:"seq"`
83		Tickets   []ticket                     `json:"tickets"`
84		SubmitIDs []string                     `json:"submitIds"`
85		OpIDs     map[string]map[string]string `json:"opIds"`
86	}
87	
88	// ticketStore 持久化工单、已成功的提交标识与分派操作标识，所有方法并发安全。
89	type ticketStore struct {
90		mu       sync.Mutex
91		path     string
92		seq      int
93		tickets  []ticket
94		bySubmit map[string]int               // submitId -> tickets 下标
95		byID     map[string]int               // 工单编号 -> tickets 下标
96		opIDs    map[string]map[string]string // 工单编号 -> operationId -> 成功提交时的负责人
97	}
98	
99	func loadStore(path string) (*ticketStore, error) {
100		s := &ticketStore{
101			path:     path,
102			tickets:  []ticket{},
103			bySubmit: map[string]int{},
104			byID:     map[string]int{},
105			opIDs:    map[string]map[string]string{},
106		}
107		raw, err := os.ReadFile(path)
108		if err != nil {
109			return nil, err
110		}
111		var data storeFile
112		if err := json.Unmarshal(raw, &data); err != nil {
113			// 兼容旧版本的纯数组文件 []。
114			var legacy []ticket
115			if legacyErr := json.Unmarshal(raw, &legacy); legacyErr != nil {
116				return nil, err
117			}
118			data.Tickets = legacy
119		}
120		if data.Tickets != nil {
121			s.tickets = data.Tickets
122		}
123		s.seq = data.Seq
124		if data.OpIDs != nil {
125			s.opIDs = data.OpIDs
126		}
127		for i, t := range s.tickets {
128			// 编号是重启后不重复的最终依据；旧数据缺少 seq 时从编号恢复。
129			var n int
130			if _, scanErr := fmt.Sscanf(t.ID, "TKT-%d", &n); scanErr == nil && n > s.seq {
131				s.seq = n
132			}
133			s.byID[t.ID] = i
134			if t.Assignments == nil {
135				// 已有工单没有分派记录时展示为空，不补造历史。
136				s.tickets[i].Assignments = []assignmentRecord{}
137			}
138			if i < len(data.SubmitIDs) && data.SubmitIDs[i] != "" {
139				s.bySubmit[data.SubmitIDs[i]] = i
140			}
141		}
142		return s, nil
143	}
144	
145	// persistLocked 将当前数据原子写入磁盘，调用方须持有 s.mu。
146	func (s *ticketStore) persistLocked() error {
147		ids := make([]string, len(s.tickets))
148		for id, i := range s.bySubmit {
149			if i >= 0 && i < len(ids) {
150				ids[i] = id
151			}
152		}
153		data := storeFile{Seq: s.seq, Tickets: s.tickets, SubmitIDs: ids, OpIDs: s.opIDs}
154		buf, err := json.MarshalIndent(data, "", "  ")
155		if err != nil {
156			return err
157		}
158		buf = append(buf, '\n')
159		tmp := s.path + ".tmp"
160		if err := os.WriteFile(tmp, buf, 0600); err != nil {
161			return err
162		}
163		return os.Rename(tmp, s.path)
164	}
165	
166	var errConflict = errors.New("submit id reused with different content")
167	var errNotFound = errors.New("ticket not found")
168	var errOpConflict = errors.New("operation id reused with different assignee")
169	
170	// create 校验后的数据登记为工单。同一提交标识、相同内容为幂等重放，
171	// 返回已有工单且 replay=true；同一标识不同内容返回 errConflict 且不改数据。
172	func (s *ticketStore) create(in ticketInput) (t ticket, replay bool, err error) {
173		s.mu.Lock()
174		defer s.mu.Unlock()
175		if idx, ok := s.bySubmit[in.SubmitID]; ok {
176			existing := s.tickets[idx]
177			if sameTicketContent(existing, in) {
178				return existing, true, nil
179			}
180			return ticket{}, false, errConflict
181		}
182		s.seq++
183		now := time.Now().Format(timeLayout)
184		t = ticket{
185			ID:             fmt.Sprintf("TKT-%06d", s.seq),
186			Description:    in.Description,
187			ContactName:    in.ContactName,
188			ContactInfo:    in.ContactInfo,
189			Source:         in.Source,
190			Category:       in.Category,
191			Priority:       in.Priority,
192			AttachmentNote: in.AttachmentNote,
193			OrderNumber:    in.OrderNumber,
194			Status:         "待处理",
195			Assignee:       "未分派",
196			CreatedAt:      now,
197			UpdatedAt:      now,
198			Assignments:    []assignmentRecord{},
199		}
200		s.tickets = append(s.tickets, t)
201		s.bySubmit[in.SubmitID] = len(s.tickets) - 1
202		s.byID[t.ID] = len(s.tickets) - 1
203		if err := s.persistLocked(); err != nil {
204			// 保存失败：回滚内存中的本次变更，登记不算完成。
205			delete(s.bySubmit, in.SubmitID)
206			delete(s.byID, t.ID)
207			s.tickets = s.tickets[:len(s.tickets)-1]
208			s.seq--
209			return ticket{}, false, err
210		}
211		return t, false, nil
212	}
213	
214	// assign 处理一次分派或转交。负责人与当前相同、或操作标识已成功提交过相同负责人时
215	// 为幂等成功，不改动负责人、时间与记录；操作标识已成功提交过不同负责人时返回
216	// errOpConflict 且不改动任何内容；工单不存在时返回 errNotFound。
217	func (s *ticketStore) assign(ticketID, assignee, opID string) (t ticket, changed bool, err error) {
218		s.mu.Lock()
219		defer s.mu.Unlock()
220		idx, ok := s.byID[ticketID]
221		if !ok {
222			return ticket{}, false, errNotFound
223		}
224		opMap, hadMap := s.opIDs[ticketID]
225		if !hadMap {
226			opMap = map[string]string{}
227		}
228		if prev, seen := opMap[opID]; seen {
229			// 同一操作标识已成功提交过：负责人相同即返回成功，不再修改负责人、
230			// 时间或记录；即使工单后来已转交给别人，重试旧操作也不能把负责人改回去。
231			if prev == assignee {
232				return s.tickets[idx], false, nil
233			}
234			return ticket{}, false, errOpConflict
235		}
236	
237		cur := s.tickets[idx]
238		updated := cur
239		if cur.Assignee != assignee {
240			// 实际变化才追加分派记录，并刷新最近处理时间；登记内容与编号等保持不变。
241			updated.Assignee = assignee
242			updated.UpdatedAt = time.Now().Format(timeLayout)
243			updated.Assignments = append(append([]assignmentRecord(nil), cur.Assignments...), assignmentRecord{
244				From: cur.Assignee,
245				To:   assignee,
246				At:   updated.UpdatedAt,
247			})
248			changed = true
249		}
250		opMap[opID] = assignee
251		if !hadMap {
252			s.opIDs[ticketID] = opMap
253		}
254		s.tickets[idx] = updated
255		if err := s.persistLocked(); err != nil {
256			// 保存失败：回滚内存中的本次变更，操作标识不算成功，修正后可重试。
257			s.tickets[idx] = cur
258			delete(opMap, opID)
259			if !hadMap {
260				delete(s.opIDs, ticketID)
261			}
262			return ticket{}, false, err
263		}
264		return updated, changed, nil
265	}
266	func (s *ticketStore) list() []ticket {
267		s.mu.Lock()
268		defer s.mu.Unlock()
269		out := make([]ticket, len(s.tickets))
270		copy(out, s.tickets)
271		sort.SliceStable(out, func(i, j int) bool {
272			if out[i].CreatedAt != out[j].CreatedAt {
273				return out[i].CreatedAt > out[j].CreatedAt
274			}
275			return out[i].ID > out[j].ID
276		})
277		return out
278	}
279	
280	// sameTicketContent 按文字处理规则比较已有工单与本次提交（提交标识除外）。
281	func sameTicketContent(t ticket, in ticketInput) bool {
282		return t.Description == in.Description &&
283			t.ContactName == in.ContactName &&
284			t.ContactInfo == in.ContactInfo &&
285			t.Source == in.Source &&
286			t.Category == in.Category &&
287			t.Priority == in.Priority &&
288			t.AttachmentNote == in.AttachmentNote &&
289			t.OrderNumber == in.OrderNumber
290	}
291	
292	// validateInput 按页面与接口一致的规则校验，并对文字字段去除首尾空白。
293	// 描述与附件说明只去除整体首尾空白，正文内部换行保留。
294	func validateInput(in *ticketInput) error {
295		in.Description = strings.TrimSpace(in.Description)
296		in.ContactName = strings.TrimSpace(in.ContactName)
297		in.ContactInfo = strings.TrimSpace(in.ContactInfo)
298		in.Source = strings.TrimSpace(in.Source)
299		in.Category = strings.TrimSpace(in.Category)
300		in.Priority = strings.TrimSpace(in.Priority)
301		in.AttachmentNote = strings.TrimSpace(in.AttachmentNote)
302		// 联系方式与订单号始终是字符串，不做数字转换，前导零不会丢失。
303		in.OrderNumber = strings.TrimSpace(in.OrderNumber)
304		in.SubmitID = strings.TrimSpace(in.SubmitID)
305	
306		var missing []string
307		for _, f := range []struct{ name, value string }{
308			{"description", in.Description},
309			{"contactName", in.ContactName},
310			{"contactInfo", in.ContactInfo},
311			{"category", in.Category},
312			{"submitId", in.SubmitID},
313		} {
314			if f.value == "" {
315				missing = append(missing, f.name)
316			}
317		}
318		if len(missing) > 0 {
319			return fmt.Errorf("missing or empty required fields: %s", strings.Join(missing, ", "))
320		}
321		if !oneOf(in.Source, validSources) {
322			return fmt.Errorf("invalid source: %q; allowed: %s", in.Source, strings.Join(validSources, "/"))
323		}
324		if !oneOf(in.Priority, validPriorities) {
325			return fmt.Errorf("invalid priority: %q; allowed: %s", in.Priority, strings.Join(validPriorities, "/"))
326		}
327		return nil
328	}
329	
330	func oneOf(v string, allowed []string) bool {
331		for _, a := range allowed {
332			if v == a {
333				return true
334			}
335		}
336		return false
337	}
338	
339	func newSubmitID() string {
340		b := make([]byte, 16)
341		if _, err := rand.Read(b); err != nil {
342			// rand 失败极不可能发生；退回纳秒时间戳仍能给出非空标识。
343			return fmt.Sprintf("sub-%d", time.Now().UnixNano())
344		}
345		return "sub-" + hex.EncodeToString(b)
346	}
347	
348	func respond(w http.ResponseWriter, status int, allow string, value any) {
349		w.Header().Set("Content-Type", "application/json; charset=utf-8")
350		if allow != "" {
351			w.Header().Set("Allow", allow)
352		}
353		w.WriteHeader(status)
354		_ = json.NewEncoder(w).Encode(value)
355	}
356	
357	func run() error {
358		if len(os.Args) < 2 {
359			printHelp()
360			return errors.New("expected serve or --help")
361		}
362		if os.Args[1] == "--help" || os.Args[1] == "-h" {
363			printHelp()
364			return nil
365		}
366		if os.Args[1] != "serve" {
367			return errors.New("expected serve or --help")
368		}
369		args := flag.NewFlagSet("case-dock serve", flag.ContinueOnError)
370		args.SetOutput(os.Stdout)
371		host := args.String("host", "127.0.0.1", "address to bind")
372		port := args.Int("port", 8080, "port to bind; 0 selects an available port")
373		data := args.String("data-dir", "data", "directory for local records")
374		if err := args.Parse(os.Args[2:]); errors.Is(err, flag.ErrHelp) {
375			return nil
376		} else if err != nil {
377			return err
378		}
379		if args.NArg() != 0 {
380			return errors.New("unexpected positional argument")
381		}
382		if *port < 0 || *port > 65535 {
383			return errors.New("port must be between 0 and 65535")
384		}
385		if err := os.MkdirAll(*data, 0700); err != nil {
386			return err
387		}
388		dataFile := filepath.Join(*data, "tickets.json")
389		if _, err := os.Stat(dataFile); errors.Is(err, os.ErrNotExist) {
390			buf, err := json.MarshalIndent(storeFile{
391				Seq:       0,
392				Tickets:   []ticket{},
393				SubmitIDs: []string{},
394				OpIDs:     map[string]map[string]string{},
395			}, "", "  ")
396			if err != nil {
397				return err
398			}
399			buf = append(buf, '\n')
400			if err := os.WriteFile(dataFile, buf, 0600); err != nil {
401				return err
402			}
403		} else if err != nil {
404			return err
405		}
406		store, err := loadStore(dataFile)
407		if err != nil {
408			return fmt.Errorf("load %s: %w", dataFile, err)
409		}
410	
411		mux := http.NewServeMux()
412		mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
413			if r.URL.Path != "/" {
414				respond(w, http.StatusNotFound, "", map[string]string{"error": "not found"})
415				return
416			}
417			if r.Method != http.MethodGet {
418				respond(w, http.StatusMethodNotAllowed, "GET", map[string]string{"error": "method not allowed"})
419				return
420			}
421			w.Header().Set("Content-Type", "text/html; charset=utf-8")
422			_, _ = io.WriteString(w, page)
423		})
424		mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
425			if r.Method != http.MethodGet {
426				respond(w, http.StatusMethodNotAllowed, "GET", map[string]string{"error": "method not allowed"})
427				return
428			}
429			respond(w, http.StatusOK, "", map[string]string{"status": "ok", "product": product})
430		})
431		mux.HandleFunc("/api/tickets", func(w http.ResponseWriter, r *http.Request) {
432			switch r.Method {
433			case http.MethodGet:
434				tickets := store.list()
435				respond(w, http.StatusOK, "", map[string]any{resourceName: tickets})
436			case http.MethodPost:
437				body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
438				if err != nil {
439					respond(w, http.StatusBadRequest, "", map[string]string{"error": "unable to read request body"})
440					return
441				}
442				dec := json.NewDecoder(bytes.NewReader(body))
443				var in ticketInput
444				if decErr := dec.Decode(&in); decErr != nil {
445					if errors.Is(decErr, io.EOF) {
446						decErr = errors.New("request body is empty")
447					}
448					respond(w, http.StatusBadRequest, "", map[string]string{"error": "invalid JSON: " + decErr.Error()})
449					return
450				}
451				var tail json.RawMessage
452				if decErr := dec.Decode(&tail); !errors.Is(decErr, io.EOF) {
453					respond(w, http.StatusBadRequest, "", map[string]string{"error": "invalid JSON: trailing data after the JSON object"})
454					return
455				}
456				if err := validateInput(&in); err != nil {
457					respond(w, http.StatusBadRequest, "", map[string]string{"error": err.Error()})
458					return
459				}
460				t, replay, err := store.create(in)
461				if errors.Is(err, errConflict) {
462					respond(w, http.StatusConflict, "", map[string]string{"error": "submit id was already used with different content"})
463					return
464				}
465				if err != nil {
466					respond(w, http.StatusInternalServerError, "", map[string]string{"error": "unable to save ticket"})
467					return
468				}
469				status := http.StatusCreated
470				if replay {
471					status = http.StatusOK
472				}
473				respond(w, status, "", t)
474			default:
475				respond(w, http.StatusMethodNotAllowed, "GET, POST", map[string]string{"error": "method not allowed"})
476			}
477		})
478		mux.HandleFunc("POST /api/tickets/{id}/assignment", func(w http.ResponseWriter, r *http.Request) {
479			id := r.PathValue("id")
480			body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
481			if err != nil {
482				respond(w, http.StatusBadRequest, "", map[string]string{"error": "unable to read request body"})
483				return
484			}
485			dec := json.NewDecoder(bytes.NewReader(body))
486			var in assignmentInput
487			if decErr := dec.Decode(&in); decErr != nil {
488				if errors.Is(decErr, io.EOF) {
489					decErr = errors.New("request body is empty")
490				}
491				respond(w, http.StatusBadRequest, "", map[string]string{"error": "invalid JSON: " + decErr.Error()})
492				return
493			}
494			var tail json.RawMessage
495			if decErr := dec.Decode(&tail); !errors.Is(decErr, io.EOF) {
496				respond(w, http.StatusBadRequest, "", map[string]string{"error": "invalid JSON: trailing data after the JSON object"})
497				return
498			}
499			assignee := strings.TrimSpace(in.Assignee)
500			opID := strings.TrimSpace(in.OperationID)
501			if assignee == "" {
502				respond(w, http.StatusBadRequest, "", map[string]string{"error": "assignee must not be empty"})
503				return
504			}
505			if assignee == "未分派" {
506				respond(w, http.StatusBadRequest, "", map[string]string{"error": `assignee cannot be "未分派"`})
507				return
508			}
509			if opID == "" {
510				respond(w, http.StatusBadRequest, "", map[string]string{"error": "operationId must not be empty"})
511				return
512			}
513			t, changed, err := store.assign(id, assignee, opID)
514			if errors.Is(err, errNotFound) {
515				respond(w, http.StatusNotFound, "", map[string]string{"error": "ticket not found: " + id})
516				return
517			}
518			if errors.Is(err, errOpConflict) {
519				respond(w, http.StatusConflict, "", map[string]string{"error": "operationId was already used with a different assignee"})
520				return
521			}
522			if err != nil {
523				respond(w, http.StatusInternalServerError, "", map[string]string{"error": "unable to save assignment"})
524				return
525			}
526			respond(w, http.StatusOK, "", map[string]any{"ticket": t, "changed": changed})
527		})
528	
529		server := &http.Server{
530			Handler:           mux,
531			ReadHeaderTimeout: 5 * time.Second,
532		}
533		listener, err := net.Listen("tcp", net.JoinHostPort(*host, fmt.Sprint(*port)))
534		if err != nil {
535			return err
536		}
537		fmt.Printf("%s listening on http://%s\n", product, listener.Addr().String())
538		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
539		defer stop()
540		failures := make(chan error, 1)
541		go func() { failures <- server.Serve(listener) }()
542		select {
543		case err := <-failures:
544			if !errors.Is(err, http.ErrServerClosed) {
545				return err
546			}
547		case <-ctx.Done():
548			shutdown, cancel := context.WithTimeout(context.Background(), 3*time.Second)
549			defer cancel()
550			if err := server.Shutdown(shutdown); err != nil {
551				return err
552			}
553		}
554		return nil
555	}
556	
557	func printHelp() {
558		fmt.Println("CaseDock - 客服工单与知识服务")
559		fmt.Println("Usage: go run . serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]")
560		fmt.Println("       go run . --help")
561		fmt.Println("Defaults: --host 127.0.0.1 --port 8080 --data-dir data")
562	}
563	
564	func main() {
565		if err := run(); err != nil {
566			fmt.Fprintln(os.Stderr, err)
567			os.Exit(1)
568		}
569	}
